    public Object parseMarket(Object market)
    {
        //
        //     {
        //         "id": "01JHN5EFT64YC4HR9KCGM5M65D",
        //         "symbol": "POL_USDT",
        //         "baseCurrency": "POL",
        //         "quoteCurrency": "USDT",
        //         "baseMinSize": "1.00000000",
        //         "quoteMinSize": "5.00000000",
        //         "baseMaxSize": "50000.00000000",
        //         "quoteMaxSize": "10000000000.00000000",
        //         "basePrec": "1",
        //         "quotePrec": "4"
        //     }
        //
        Object marketId = this.safeString(market, "symbol");
        if (Helpers.isTrue(Helpers.isEqual(marketId, null)))
        {
            throw new ExchangeError((String)Helpers.add(this.id, " parseMarket() missing marketId")) ;
        }
        Object parts = Helpers.split(marketId, "_");
        Object baseId = Helpers.GetValue(parts, 0);
        Object quoteId = Helpers.GetValue(parts, 1);
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object fees = this.safeDict(this.fees, "trading");
        final Object finalMarketId = marketId;
        final Object finalBase = base;
        return this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
            put( "id", finalMarketId );
            put( "symbol", Helpers.add(Helpers.add(finalBase, "/"), quote) );
            put( "base", finalBase );
            put( "quote", quote );
            put( "baseId", baseId );
            put( "quoteId", quoteId );
            put( "active", true );
            put( "type", "spot" );
            put( "subType", null );
            put( "spot", true );
            put( "margin", false );
            put( "swap", false );
            put( "future", false );
            put( "option", false );
            put( "contract", false );
            put( "settle", null );
            put( "settleId", null );
            put( "contractSize", null );
            put( "linear", null );
            put( "inverse", null );
            put( "taker", Cryptomus.this.safeNumber(fees, "taker") );
            put( "maker", Cryptomus.this.safeNumber(fees, "maker") );
            put( "percentage", Cryptomus.this.safeBool(fees, "percentage") );
            put( "tierBased", null );
            put( "feeSide", Cryptomus.this.safeString(fees, "feeSide") );
            put( "expiry", null );
            put( "expiryDatetime", null );
            put( "strike", null );
            put( "optionType", null );
            put( "precision", new java.util.HashMap<String, Object>() {{
                put( "amount", Cryptomus.this.parseNumber(Cryptomus.this.parsePrecision(Cryptomus.this.safeString(market, "quotePrec"))) );
                put( "price", Cryptomus.this.parseNumber(Cryptomus.this.parsePrecision(Cryptomus.this.safeString(market, "basePrec"))) );
            }} );
            put( "limits", new java.util.HashMap<String, Object>() {{
                put( "amount", new java.util.HashMap<String, Object>() {{
                    put( "min", Cryptomus.this.safeNumber(market, "quoteMinSize") );
                    put( "max", Cryptomus.this.safeNumber(market, "quoteMaxSize") );
                }} );
                put( "price", new java.util.HashMap<String, Object>() {{
                    put( "min", Cryptomus.this.safeNumber(market, "baseMinSize") );
                    put( "max", Cryptomus.this.safeNumber(market, "baseMaxSize") );
                }} );
                put( "leverage", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "cost", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
            }} );
            put( "created", null );
            put( "info", market );
        }});
    }

    /**
     * @method
     * @name cryptomus#fetchCurrencies
     * @description fetches all available currencies on an exchange
     * @see https://doc.cryptomus.com/personal/market-cap/assets
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an associative dictionary of currencies
     */
    public java.util.concurrent.CompletableFuture<Object> fetchCurrencies(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            Object response = (this.publicGetV1ExchangeMarketAssets(parameters)).join();
            //
            //     {
            //         'state': '0',
            //         'result': [
            //             {
            //                 'currency_code': 'USDC',
            //                 'network_code': 'bsc',
            //                 'can_withdraw': true,
            //                 'can_deposit': true,
            //                 'min_withdraw': '1.00000000',
            //                 'max_withdraw': '10000000.00000000',
            //                 'max_deposit': '10000000.00000000',
            //                 'min_deposit': '1.00000000'
            //             },
            //             ...
            //         ]
            //     }
            //
            Object coins = this.safeList(response, "result");
            Object groupedById = this.groupBy(coins, "currency_code");
            Object groupedArray = Helpers.objectValues(groupedById);
            return this.parseCurrencies(groupedArray);
        });

    }

    public Object parseCurrency(Object rawCurrency)
    {
        // currency here is array of networks
        Object id = null; // all entries have same id, as they were grouped by
        Object code = null;
        Object networks = new java.util.HashMap<String, Object>() {{}};
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(rawCurrency)); i++)
        {
            Object networkEntry = Helpers.GetValue(rawCurrency, i);
            // set ID on first loop
            if (Helpers.isTrue(Helpers.isEqual(id, null)))
            {
                id = this.safeString(networkEntry, "currency_code");
                code = this.safeCurrencyCode(id);
            }
            Object networkId = this.safeString(networkEntry, "network_code");
            Object networkCode = this.networkIdToCode(networkId, code);
            if (Helpers.isTrue(!Helpers.isEqual(networkCode, null)))
            {
                final Object finalNetworkCode = networkCode;
                Helpers.addElementToObject(networks, networkCode, new java.util.HashMap<String, Object>() {{
    put( "id", networkId );
    put( "network", finalNetworkCode );
    put( "limits", new java.util.HashMap<String, Object>() {{
        put( "withdraw", new java.util.HashMap<String, Object>() {{
            put( "min", Cryptomus.this.safeNumber(networkEntry, "min_withdraw") );
            put( "max", Cryptomus.this.safeNumber(networkEntry, "max_withdraw") );
        }} );
        put( "deposit", new java.util.HashMap<String, Object>() {{
            put( "min", Cryptomus.this.safeNumber(networkEntry, "min_deposit") );
            put( "max", Cryptomus.this.safeNumber(networkEntry, "max_deposit") );
        }} );
    }} );
    put( "active", null );
    put( "deposit", Cryptomus.this.safeBool(networkEntry, "can_deposit") );
    put( "withdraw", Cryptomus.this.safeBool(networkEntry, "can_withdraw") );
    put( "fee", null );
    put( "precision", null );
    put( "info", networkEntry );
}});
            }
        }
        final Object finalId = id;
        final Object finalCode = code;
        return this.safeCurrencyStructure(new java.util.HashMap<String, Object>() {{
            put( "id", finalId );
            put( "code", finalCode );
            put( "networks", networks );
            put( "info", rawCurrency );
        }});
    }

    /**
     * @method
     * @name cryptomus#fetchTickers
     * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
     * @see https://doc.cryptomus.com/personal/market-cap/tickers
     * @param {string[]} [symbols] unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
     */
    public java.util.concurrent.CompletableFuture<Object> fetchTickers(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object symbols = Helpers.getArg(optionalArgs, 0, null);
            Object parameters = Helpers.getArg(optionalArgs, 1, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            symbols = this.marketSymbols(symbols);
            Object response = (this.publicGetV1ExchangeMarketTickers(parameters)).join();
            //
            //     {
            //         "data": [
            //         {
            //             "currency_pair": "MATIC_USDT",
            //             "last_price": "0.342",
            //             "base_volume": "1676.84092771",
            //             "quote_volume": "573.48033609043"
            //         },
            //         ...
            //     }
            //
            Object data = this.safeList(response, "data");
            return this.parseTickers(data, symbols);
        });

    }

    public Object parseTicker(Object ticker, Object... optionalArgs)
    {
        //
        //     {
        //         "currency_pair": "XMR_USDT",
        //         "last_price": "158.04829772",
        //         "base_volume": "0.35185785",
        //         "quote_volume": "55.523761128544"
        //     }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(ticker, "currency_pair");
        market = this.safeMarket(marketId, market);
        Object symbol = Helpers.GetValue(market, "symbol");
        Object last = this.safeString(ticker, "last_price");
        return this.safeTicker(new java.util.HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", null );
            put( "datetime", null );
            put( "high", null );
            put( "low", null );
            put( "bid", null );
            put( "bidVolume", null );
            put( "ask", null );
            put( "askVolume", null );
            put( "vwap", null );
            put( "open", null );
            put( "close", last );
            put( "last", last );
            put( "previousClose", null );
            put( "change", null );
            put( "percentage", null );
            put( "average", null );
            put( "baseVolume", Cryptomus.this.safeString(ticker, "base_volume") );
            put( "quoteVolume", Cryptomus.this.safeString(ticker, "quote_volume") );
            put( "info", ticker );
        }}, market);
    }

